import hashlib
def shingles(text, k=5):
    w = text.split()
    return {hashlib.md5(" ".join(w[i:i+k]).encode()).hexdigest()[:8]
            for i in range(max(1, len(w)-k+1))}
docs = ["the quick brown fox jumps", "the quick brown fox jumps",
        "a totally different sentence here now"]
seen, kept = set(), []
for d in docs:
    sig = next(iter(shingles(d)))
    if sig not in seen:
        seen.add(sig); kept.append(d)
print("kept:", len(kept), "of", len(docs))

def mrr(ranked, relevant, k=10):
    for i, doc in enumerate(ranked[:k], 1):
        if doc in relevant: return 1.0 / i
    return 0.0
print("MRR@10:", mrr(["d3", "d1", "d9"], {"d1"}))

