def chunk(text, size=2048, overlap=128):
    toks = text.split()
    return [" ".join(toks[i:i+size])
            for i in range(0, len(toks), size - overlap)]
doc = "word " * 5000
print("chunks:", len(chunk(doc)))

import math
def pass_at_k(n, c, k):
    if n - c < k: return 1.0
    return 1.0 - math.comb(n - c, k) / math.comb(n, k)
print("pass@1:", round(pass_at_k(20, 7, 1), 3))
print("pass@10:", round(pass_at_k(20, 7, 10), 3))
